"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7946],{55258:e=>{e.exports=JSON.parse('{"functions":[{"name":"CreateBeam","desc":"Creates a `Beam` between `att0` and `att1`, applies all visual properties\\nfrom `GrabHookConfig.Visuals`, and parents it to `parent`.","params":[{"name":"att0","desc":"Origin attachment (typically on the tool handle).","lua_type":"Attachment"},{"name":"att1","desc":"Target attachment (typically on the junk part).","lua_type":"Attachment"},{"name":"parent","desc":"Where to parent the created `Beam`.","lua_type":"Instance"}],"returns":[{"desc":"The newly created beam.","lua_type":"Beam"}],"function_type":"static","source":{"line":40,"path":"src/ReplicatedStorage/SharedModules/GrabHookVisuals.luau"}},{"name":"AnimateProjectile","desc":"Drives the three-phase grabhook animation for the tool user on\\n`RunService.RenderStepped`:\\n\\n1. **FLIGHT** \u2014 the hook attachment lerps toward `hitPos` over a duration\\n   derived from distance and `GrabHookConfig.Physics.Speed`, with a\\n   sinusoidal rope wave that decays as the hook approaches.\\n2. **LATCH** \u2014 a single transition frame that flattens the curve and\\n   records the retract distance.\\n3. **RETRACT** \u2014 `targetPart.Position` is lerped back to the handle each\\n   frame.  When retraction completes (or if `targetPart` leaves\\n   `workspace`), the beam and junk attachment are destroyed and\\n   `onCleanup` is called.\\n\\nReturns the `RBXScriptConnection` so the caller can disconnect early if\\nneeded.","params":[{"name":"beam","desc":"The beam created by `CreateBeam`.","lua_type":"Beam"},{"name":"startAtt","desc":"The origin attachment (handle side).","lua_type":"Attachment"},{"name":"targetPart","desc":"The junk part being reeled in.","lua_type":"BasePart"},{"name":"hitPos","desc":"The world position where the hook latched.","lua_type":"Vector3"},{"name":"onCleanup","desc":"Optional callback invoked when the animation ends.","lua_type":"(() -> ())?"},{"name":"retractSpeed","desc":"Reel speed in studs/s (perks applied); defaults to `GrabHookConfig.Physics.RetractSpeed`.","lua_type":"number?"}],"returns":[{"desc":"The `RenderStepped` connection driving the animation.","lua_type":"RBXScriptConnection"}],"function_type":"static","source":{"line":81,"path":"src/ReplicatedStorage/SharedModules/GrabHookVisuals.luau"}},{"name":"AnimateObserver","desc":"Drives a simplified rope-wave animation for spectating clients.  Since\\nthe observer receives the event after server confirmation the hook is\\nalready assumed latched; the wave simply decays over time using a\\nstandard `1 / (1 + elapsed * decay)` envelope.\\n\\nAutomatically disconnects and destroys `startAtt` when the `Beam` is\\ndestroyed by the owning controller.","params":[{"name":"beam","desc":"The beam to animate.","lua_type":"Beam"},{"name":"startAtt","desc":"The origin attachment to clean up when done.","lua_type":"Attachment"}],"returns":[{"desc":"The `RenderStepped` connection driving the animation.","lua_type":"RBXScriptConnection"}],"function_type":"static","source":{"line":174,"path":"src/ReplicatedStorage/SharedModules/GrabHookVisuals.luau"}}],"properties":[],"types":[],"name":"GrabHookVisuals","desc":"Client-side beam and rope animation helpers for the grabhook tool.\\n\\nAll visual parameters (colour, width, curve amplitude, travel speed, etc.)\\nare read from `GrabHookConfig.Visuals` and `GrabHookConfig.Physics` so\\nthat tuning never requires touching this module.\\n\\nThree entry points are provided:\\n\\n- `CreateBeam` \u2014 builds a `Beam` instance between two attachments.\\n- `AnimateProjectile` \u2014 three-phase flight/latch/retract animation for the\\n  tool user.\\n- `AnimateObserver` \u2014 simplified decay animation for spectating clients\\n  who observe another player\'s grabhook.","source":{"line":22,"path":"src/ReplicatedStorage/SharedModules/GrabHookVisuals.luau"}}')}}]);